use parth_db::exec::execute;
use parth_db::table::Database;
use parth_db::parser::Projection;
use parth_db::exec::select;

fn open(name: &str) -> Database { let dir = std::env::temp_dir().join(format!("pd_distinct_{}_{}", name, std::process::id())); let _ = std::fs::remove_dir_all(&dir); Database::open(&dir).unwrap() }
fn count(db: &Database, sql: &str) -> usize { execute(db, sql).unwrap().rows.len() }
fn dump(db: &Database, sql: &str) -> String { format!("{:?}", execute(db, sql).unwrap().rows) }

#[test]
fn duplicates_and_nulls_collapse() { let db = open("nulls"); execute(&db, "CREATE TABLE t (id INT PRIMARY KEY, n INT, r REAL)").unwrap(); execute(&db, "INSERT INTO t VALUES (1, 5, 5.0), (2, 5, 5.0), (3, NULL, NULL), (4, NULL, 2.5), (5, 7, NULL), (6, NULL, NULL)").unwrap(); assert_eq!(count(&db, "SELECT DISTINCT n FROM t"), 3); assert_eq!(count(&db, "SELECT DISTINCT r FROM t"), 3); assert_eq!(count(&db, "SELECT DISTINCT n, r FROM t"), 4); assert_eq!(count(&db, "SELECT n FROM t"), 6); }
#[test]
fn limit_offset_order_apply_after_dedup() { let db = open("order"); execute(&db, "CREATE TABLE t (id INT PRIMARY KEY, n INT)").unwrap(); execute(&db, "INSERT INTO t VALUES (1, 3), (2, 1), (3, 3), (4, 2), (5, 2), (6, 1)").unwrap(); assert_eq!(count(&db, "SELECT DISTINCT n FROM t"), 3); assert_eq!(count(&db, "SELECT DISTINCT n FROM t LIMIT 3"), 3); assert_eq!(count(&db, "SELECT DISTINCT n FROM t WHERE n > 1"), 2); assert_eq!(dump(&db, "SELECT DISTINCT n FROM t ORDER BY n DESC LIMIT 1"), dump(&db, "SELECT n FROM t WHERE id = 1")); assert_eq!(dump(&db, "SELECT DISTINCT n FROM t ORDER BY n DESC LIMIT 1 OFFSET 1"), dump(&db, "SELECT n FROM t WHERE id = 4")); assert_eq!(count(&db, "SELECT DISTINCT n FROM t LIMIT 5 OFFSET 2"), 1); assert!(execute(&db, "SELECT DISTINCT n FROM t ORDER BY id").is_err()); }
#[test]
fn unsupported_combinations_are_rejected() { let db = open("reject"); execute(&db, "CREATE TABLE t (id INT PRIMARY KEY, n INT)").unwrap(); execute(&db, "INSERT INTO t VALUES (1, 5), (2, 5)").unwrap(); for sql in ["SELECT DISTINCT * FROM t", "SELECT DISTINCT COUNT(*) FROM t", "SELECT DISTINCT n FROM t GROUP BY n"] { let message = format!("{}", execute(&db, sql).unwrap_err()); assert!(message.contains("DISTINCT"), "{message}"); } assert_eq!(count(&db, "SELECT n FROM t"), 2); }


#[test]
fn materialization_bound_applies_to_distinct() { let db = open("bound"); execute(&db, "CREATE TABLE t (id INT PRIMARY KEY, n INT)").unwrap(); let values: Vec<String> = (1..=50).map(|i| format!("({}, {})", i, i % 5)).collect(); execute(&db, &format!("INSERT INTO t VALUES {}", values.join(", "))).unwrap(); let run = |bound: (usize, usize)| select(&db, "t", Projection::Distinct(vec!["n".to_string()]), None, Vec::new(), None, None, None, 0, bound); assert!(run((10, usize::MAX)).is_err()); assert!(run((1_000_000, 100)).is_err()); assert_eq!(run((1_000_000, 134_217_728)).unwrap().rows.len(), 5); }
#[test]
fn repeated_projected_columns_count_against_the_budget() { let db = open("repeat"); execute(&db, "CREATE TABLE t (id INT PRIMARY KEY, n INT)").unwrap(); let values: Vec<String> = (1..=50).map(|i| format!("({}, {})", i, i % 5)).collect(); execute(&db, &format!("INSERT INTO t VALUES {}", values.join(", "))).unwrap(); let run = |names: &[&str], budget: usize| select(&db, "t", Projection::Distinct(names.iter().map(|n| n.to_string()).collect()), None, Vec::new(), None, None, None, 0, (1_000_000, budget)); let fit = (1..100_000).find(|b| run(&["n"], *b).is_ok()).unwrap(); assert!(run(&["n", "n", "n"], fit).is_err()); assert!(run(&["n", "n", "n"], fit * 4).is_ok()); }
#[test]
fn count_distinct_ignores_nulls_and_merges_duplicates() { let db = open("cd"); execute(&db, "CREATE TABLE t (id INT PRIMARY KEY, n INT, r REAL)").unwrap(); execute(&db, "INSERT INTO t VALUES (1, 5, 5.0), (2, 5, 5.0), (3, NULL, NULL), (4, NULL, 2.5), (5, 7, NULL), (6, NULL, NULL)").unwrap(); assert_eq!(dump(&db, "SELECT COUNT(DISTINCT n) FROM t"), "[[Int(2)]]"); assert_eq!(dump(&db, "SELECT COUNT(DISTINCT r) FROM t"), "[[Int(2)]]"); assert_eq!(dump(&db, "SELECT COUNT(DISTINCT n) FROM t WHERE id > 5"), "[[Int(0)]]"); assert!(execute(&db, "SELECT SUM(DISTINCT n) FROM t").is_err()); assert!(execute(&db, "SELECT COUNT(DISTINCT *) FROM t").is_err()); }
#[test]
fn count_distinct_repeats_and_groups_are_independent() { let db = open("cdg"); execute(&db, "CREATE TABLE g (id INT PRIMARY KEY, k INT, v INT, w INT)").unwrap(); execute(&db, "INSERT INTO g VALUES (1, 1, 10, 7), (2, 1, 10, 8), (3, 1, 20, 8), (4, 2, NULL, 9), (5, 2, 30, 9)").unwrap(); assert_eq!(dump(&db, "SELECT COUNT(DISTINCT v), COUNT(DISTINCT w), COUNT(v), COUNT(*) FROM g"), "[[Int(3), Int(3), Int(4), Int(5)]]"); assert_eq!(dump(&db, "SELECT k, COUNT(DISTINCT v), COUNT(DISTINCT w) FROM g GROUP BY k"), "[[Int(1), Int(2), Int(2)], [Int(2), Int(1), Int(1)]]"); }